{
  "claims": [
    {
      "type": "metric",
      "paragraph_id": "7-128cde0a",
      "quote": "At December 31, 2020, our balance sheet included total accrued environmental costs of $180 million, compared with $171 million at December 31, 2019, for remediation activities in the U.S. and Canada.",
      "claim": "ConocoPhillips reported total accrued environmental costs of $180 million at December 31, 2020, up from $171 million at December 31, 2019."
    },
    {
      "type": "guidance",
      "paragraph_id": "7-128cde0a",
      "quote": "We expect to incur a substantial amount of these expenditures within the next 30 years.",
      "claim": "ConocoPhillips expects to incur a substantial amount of environmental remediation expenditures over the next 30 years."
    },
    {
      "type": "risk",
      "paragraph_id": "7-14c9f3c7",
      "quote": "In the future, we may incur significant costs under both CERCLA and RCRA.",
      "claim": "ConocoPhillips may incur significant future costs under CERCLA and RCRA."
    },
    {
      "type": "risk",
      "paragraph_id": "7-96dbf4e0",
      "quote": "there can be no assurance that material costs and liabilities will not be incurred.",
      "claim": "ConocoPhillips cannot assure that material environmental costs and liabilities will not be incurred."
    },
    {
      "type": "risk",
      "paragraph_id": "7-96dbf4e0",
      "quote": "we currently do not expect any material adverse effect upon our results of operations or financial position as a result of compliance with current environmental laws and regulations.",
      "claim": "ConocoPhillips does not currently expect any material adverse effect on its results of operations or financial position from compliance with current environmental laws."
    }
  ]
}
